class_name DialogTree

@export var nodes: Array[DialogNode]
@export var start_id: StringName


func get_node(id: StringName) -> DialogNode:
	for node in nodes:
		if node.id == id:
			return node
	return null

extends Node
class_name DialogPlayer

@export var tree: DialogTree

var _flags: Dictionary = {}
var _current_node: DialogNode = null

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished


func set_flag(name: StringName):
	_flags[name] = true


func has_flag(name: StringName) -> bool:
	return _flags.has(name)


func start():
	if not tree:
		dialog_finished.emit()
		return
	_current_node = tree.get_node(tree.start_id)
	_emit_node()


func advance(choice_index: int = -1):
	if not _current_node:
		return

	# If node has choices, follow the selected branch
	if _current_node.choices and not _current_node.choices.is_empty():
		# Clamp index to valid range and filter to currently-visible choices
		var visible_choices := _visible_choices(_current_node)
		if choice_index >= 0 and choice_index < visible_choices.size():
			var next_id := visible_choices[choice_index].next_id
			_goto(next_id)
		return

	# No choices, follow next_id
	if not _current_node.next_id.is_empty():
		_goto(_current_node.next_id)
	else:
		dialog_finished.emit()
		_current_node = null


func _goto(id: StringName):
	if id.is_empty():
		dialog_finished.emit()
		_current_node = null
		return
	var node := tree.get_node(id)
	if node:
		_current_node = node
		_emit_node()
	else:
		dialog_finished.emit()
		_current_node = null


func _emit_node():
	if not _current_node:
		return
	var visible := _visible_choices(_current_node)
	var labels := []
	for choice in visible:
		labels.append(choice.label)
	line_shown.emit(_current_node.speaker, _current_node.text, labels)


func _visible_choices(node: DialogNode) -> Array:
	var visible := []
	for choice in node.choices:
		if choice.condition_flag.is_empty() or has_flag(choice.condition_flag):
			visible.append(choice)
	return visible

extends Control

@export var player: DialogPlayer
@export var speaker_label: Label
@export var text_label: RichTextLabel
@export var choices_container: VBoxContainer


func _ready():
	if player:
		player.line_shown.connect(_on_line_shown)
		player.dialog_finished.connect(_on_dialog_finished)
	# Auto-start for standalone demo
	_restart()


func _on_line_shown(speaker: String, text: String, choices: Array):
	speaker_label.text = speaker
	text_label.text = text
	# Clear old choices
	for child in choices_container.get_children():
		child.free()
	# Rebuild from visible choices labels
	for i in choices.size():
		var btn := Button.new()
		btn.text = choices[i]
		btn.pressed.connect(func(): player.advance(i))
		choices_container.add_child(btn)


func _on_dialog_finished():
	speaker_label.text = "Finished"
	text_label.text = ""
	for child in choices_container.get_children():
		child.free()


func _restart():
	player.start()

